function localeColumn(index: 0 | 1 | 2): Record<LocaleMessageKey, string> {
  return Object.fromEntries(
    Object.entries(ADDITIONAL_LOCALE_MESSAGES).map(([key, values]) => [key, values[index]]),
  ) as Record<LocaleMessageKey, string>
}

export const FR_LOCALE_MESSAGES = localeColumn(0)
export const ID_LOCALE_MESSAGES = localeColumn(1)
export const RU_LOCALE_MESSAGES = localeColumn(2)
